const createInfiniteParams = <K extends Pick<QueryKey<Options>[0], 'body' | 'headers' | 'path' | 'query'>>(queryKey: QueryKey<Options>, page: K) => {
    const params = { ...queryKey[0] };
    if (page.body) {
        params.body = {
            ...queryKey[0].body as any,
            ...page.body as any
        };
    }
    if (page.headers) {
        params.headers = {
            ...queryKey[0].headers,
            ...page.headers
        };
    }
    if (page.path) {
        params.path = {
            ...queryKey[0].path as any,
            ...page.path as any
        };
    }
    if (page.query) {
        params.query = {
            ...queryKey[0].query as any,
            ...page.query as any
        };
    }
    return params as unknown as typeof page;
};

export const importTasksListInfiniteQueryKey = (options?: Options<ImportTasksListData>): QueryKey<Options<ImportTasksListData>> => createQueryKey('importTasksList', options, true);

/**
 * List import tasks
 *
 * Paginated import tasks, optionally filtered by status.
 */
export const importTasksListInfiniteOptions = (options?: Options<ImportTasksListData>) => {
    const opts = infiniteQueryOptions<ImportTasksListResponse, ImportTasksListError, InfiniteData<ImportTasksListResponse>, QueryKey<Options<ImportTasksListData>>, number | Pick<QueryKey<Options<ImportTasksListData>>[0], 'body' | 'headers' | 'path' | 'query'>>(
    // @ts-ignore
    {
        queryFn: async ({ pageParam, queryKey, signal }) => {
            // @ts-ignore
            const page: Pick<QueryKey<Options<ImportTasksListData>>[0], 'body' | 'headers' | 'path' | 'query'> = typeof pageParam === 'object' ? pageParam : {
                query: {
                    offset: pageParam
                }
            };
            const params = createInfiniteParams(queryKey, page);
            const { data } = await importTasksList({
                ...options,
                ...params,
                signal,
                throwOnError: true
            });
            return data;
        },
        queryKey: importTasksListInfiniteQueryKey(options)
    });
    return opts as Omit<typeof opts, 'initialData'>;
};

